import React from 'react';
import Slider from './Slider';
import { sliderImages } from './homeData';

const HeroSliderSection = () => {
  return (
    <section className="hero-slider-section" id="inicio">
      <Slider slides={sliderImages} />

      <div className="hero-stats-bar">
        <div className="container">
          <div className="stats-grid">
            <div className="stat-box">
              <i className="fas fa-users"></i>
              <div>
                <span className="stat-number">5,000+</span>
                <span className="stat-text">Clientes Satisfechos</span>
              </div>
            </div>

            <div className="stat-box">
              <i className="fas fa-network-wired"></i>
              <div>
                <span className="stat-number">99.9%</span>
                <span className="stat-text">Uptime Garantizado</span>
              </div>
            </div>

            <div className="stat-box">
              <i className="fas fa-tv"></i>
              <div>
                <span className="stat-number">120+</span>
                <span className="stat-text">Canales HD</span>
              </div>
            </div>

            <div className="stat-box">
              <i className="fas fa-headset"></i>
              <div>
                <span className="stat-number">24/7</span>
                <span className="stat-text">Soporte Técnico</span>
              </div>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
};

export default HeroSliderSection;