  useEffect(() => {
    window.scrollTo(0, 0);
  }, []);

  useEffect(() => {
    const timer = window.setTimeout(() => {
      setCurrentSlide((previousSlide) =>
        (previousSlide + 1) % heroSlides.length
      );
    }, 7000);

    return () => window.clearTimeout(timer);
  }, [currentSlide]);

  const current = heroSlides[currentSlide];
  const selectedGroup = channelGroups[activeChannelGroup];

  const visibleChannels = useMemo(() => {
    const normalizedSearch = searchTerm.trim().toLowerCase();

    if (!normalizedSearch) {
      return selectedGroup.items;
    }

    return selectedGroup.items.filter(([number, name]) =>
      `${number} ${name}`.toLowerCase().includes(normalizedSearch)
    );
  }, [searchTerm, selectedGroup]);

  const goToPreviousSlide = () => {
    setCurrentSlide((previousSlide) =>
      (previousSlide - 1 + heroSlides.length) % heroSlides.length
    );
  };

  const goToNextSlide = () => {
    setCurrentSlide((previousSlide) =>
      (previousSlide + 1) % heroSlides.length
    );
  };

