import React from 'react';
import { Link } from 'react-router-dom';
import { services } from './homeData';

const ServicesSection = () => {
  return (
    <section
      className="services-corporate"
      id="servicios"
      aria-labelledby="services-section-title"
    >
      <div className="container">
        <div className="section-header">
          <h2
            className="section-title"
            id="services-section-title"
          >
            Soluciones de conectividad para todos.
          </h2>

          <p className="section-desc">
            Servicios pensados para conectar hogares, negocios,
            empresas y proyectos de nuestra comunidad.
          </p>
        </div>

        <div className="row g-4 align-items-stretch">
          {services.map((service) => (
            <div
              className="col-md-6 col-lg-4 d-flex"
              key={service.id}
            >
              <article
                className={`
                  service-card-corporate
                  service-${service.color}
                  w-100
                `}
              >
                {/* ENCABEZADO */}
                <div className="service-header-corporate">
                  <div
                    className="service-icon-corporate"
                    aria-hidden="true"
                  >
                    <i className={`fas ${service.icon}`} />
                  </div>

                  {service.badge && (
                    <span
                      className={`
                        service-badge-corporate
                        badge-${service.color}
                      `}
                    >
                      {service.badge}
                    </span>
                  )}
                </div>

                {/* CONTENIDO */}
                <div className="service-card-content">
                  <h3 className="service-title-corporate">
                    {service.title}
                  </h3>

                  <p className="service-desc-corporate">
                    {service.description}
                  </p>

                  {/* INFORMACIÓN DESTACADA */}
                  <div className="service-highlight-corporate">
                    <div className="service-highlight-header">
                      <i
                        className={`fas ${service.highlight.icon}`}
                        aria-hidden="true"
                      />

                      <span>{service.highlight.label}</span>
                    </div>

                    <div className="service-highlight-values">
                      {service.highlight.values.map((value) => (
                        <span
                          className="service-highlight-value"
                          key={value}
                        >
                          {value}
                        </span>
                      ))}
                    </div>
                  </div>

                  {/* CARACTERÍSTICAS */}
                  <ul className="service-features-corporate">
                    {service.features.map((feature) => (
                      <li key={feature}>
                        <i
                          className="fas fa-check-circle"
                          aria-hidden="true"
                        />

                        <span>{feature}</span>
                      </li>
                    ))}
                  </ul>
                </div>

                {/* BOTÓN DE NAVEGACIÓN INTERNA */}
                <Link
                  to={service.link}
                  className={`
                    btn
                    btn-service-corporate
                    btn-${service.color}
                  `}
                  aria-label={`${service.buttonText}: ${service.title}`}
                >
                  <span>{service.buttonText}</span>

                  <i
                    className="fas fa-arrow-right"
                    aria-hidden="true"
                  />
                </Link>
              </article>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
};

export default ServicesSection;