import React, {
  useCallback,
  useEffect,
  useRef,
  useState,
} from 'react';

import '../css/Slider.css';

/* =========================================================
   CARGA AUTOMÁTICA DE VIDEOS E IMÁGENES
   =========================================================
   Funciona con React + Create React App (react-scripts/Webpack).

   Estructura esperada:

   src/
   ├── assets/
   │   └── slider/
   │       ├── video-01.mp4
   │       ├── imagen-01.jpg
   │       ├── video-02.mp4
   │       └── imagen-02.jpg
   └── components/
       ├── Slider.jsx
       └── Slider.css

   Si Slider.jsx está en src/components/Slider/Slider.jsx,
   cambia '../assets/slider' por '../../assets/slider'.
   ========================================================= */

const mediaContext = require.context(
  '../assets/slider',
  true,
  /\.(mp4|webm|ogg|jpg|jpeg|png|webp|avif|gif)$/i
);

const VIDEO_EXTENSIONS = new Set([
  'mp4',
  'webm',
  'ogg',
]);

const IMAGE_EXTENSIONS = new Set([
  'jpg',
  'jpeg',
  'png',
  'webp',
  'avif',
  'gif',
]);

const IMAGE_INTERVAL = 6500;
const EMPTY_MEDIA_INTERVAL = 6500;
const VIDEO_FALLBACK_INTERVAL = 12000;

const getFileName = (path) => {
  return path.split('/').pop() || path;
};

const getFileNameWithoutExtension = (path) => {
  return getFileName(path).replace(/\.[^.]+$/, '');
};

const getFileExtension = (path) => {
  return path
    .split('.')
    .pop()
    ?.toLowerCase() || '';
};

const naturalSort = (itemA, itemB) => {
  return getFileName(itemA.path).localeCompare(
    getFileName(itemB.path),
    'es',
    {
      numeric: true,
      sensitivity: 'base',
    }
  );
};

const importedMediaFiles = mediaContext
  .keys()
  .map((path) => {
    const importedFile = mediaContext(path);

    const mediaUrl =
      importedFile?.default || importedFile;

    const extension = getFileExtension(path);

    let type = null;

    if (VIDEO_EXTENSIONS.has(extension)) {
      type = 'video';
    }

    if (IMAGE_EXTENSIONS.has(extension)) {
      type = 'image';
    }

    return {
      id: getFileNameWithoutExtension(path),
      path,
      media: mediaUrl,
      extension,
      type,
    };
  })
  .filter((item) => item.type !== null);

/*
 * Los archivos se separan para construir el orden:
 * Video 1 → Imagen 1 → Video 2 → Imagen 2.
 */
const videos = importedMediaFiles
  .filter((item) => item.type === 'video')
  .sort(naturalSort);

const images = importedMediaFiles
  .filter((item) => item.type === 'image')
  .sort(naturalSort);

/*
 * Construye la colección base de multimedia.
 *
 * La secuencia definitiva no se crea aquí. Se asigna después
 * directamente según la posición de cada diapositiva:
 *
 * posición 0: video
 * posición 1: imagen
 * posición 2: video
 * posición 3: imagen
 *
 * De esa forma, la cantidad de textos nunca puede romper
 * la secuencia Video → Imagen.
 */
const mediaItems = [
  ...videos,
  ...images,
];

if (process.env.NODE_ENV === 'development') {
  console.info(
    '[CAPSOS Slider] Multimedia encontrada:',
    {
      videos: videos.map((item) => item.path),
      imagenes: images.map((item) => item.path),
      ordenFinal: mediaItems.map(
        (item) => `${item.type}: ${item.path}`
      ),
    }
  );
}

