/* =========================================================
   UNIÓN DE TEXTOS Y MULTIMEDIA
   =========================================================
   REGLAS:

   1. Si existe un solo archivo multimedia:
      se reutiliza en todas las diapositivas.

   2. Si existen varios archivos:
      se asignan en el orden Video → Imagen.

   3. Si hay menos archivos que textos:
      se repiten cíclicamente; nunca queda un espacio vacío.

   4. Si no existe ningún archivo:
      se muestra el fondo tecnológico del panel derecho.

   5. Si sobran archivos:
      se muestran con el panel izquierdo vacío.
   ========================================================= */

const createSlides = () => {
  const hasVideos = videos.length > 0;
  const hasImages = images.length > 0;
  const hasMedia = hasVideos || hasImages;

  /*
   * Cuando existen videos e imágenes, la cantidad de posiciones
   * multimedia necesarias para mostrar todos los archivos al menos
   * una vez es:
   *
   * 2 × la cantidad mayor entre videos e imágenes.
   *
   * La cantidad total de diapositivas también considera los textos. Cuando los textos se terminan, vuelven a comenzar desde el primero.
   */
  const alternatingMediaLength =
    hasVideos && hasImages
      ? Math.max(videos.length, images.length) * 2
      : Math.max(videos.length, images.length);

  const totalSlides = Math.max(
    slideContent.length,
    alternatingMediaLength,
    1
  );

  return Array.from(
    { length: totalSlides },
    (_, index) => {
      /*
       * Los textos también se repiten cíclicamente.
       *
       * Si hay más videos/imágenes que bloques de texto,
       * el contenido vuelve a comenzar desde el texto 1.
       *
       * Si no existe contenido textual, el panel izquierdo
       * permanece vacío.
       */
      const content =
        slideContent.length > 0
          ? slideContent[
              index % slideContent.length
            ]
          : null;

      let mediaItem = null;

      /*
       * REGLA PRINCIPAL:
       *
       * Cuando existen ambos tipos, las posiciones pares siempre
       * usan video y las impares siempre usan imagen.
       *
       * Los índices internos se repiten cíclicamente, por lo que
       * nunca se rompe:
       *
       * Video → Imagen → Video → Imagen
       */
      if (hasVideos && hasImages) {
        const mediaPairIndex = Math.floor(index / 2);

        mediaItem =
          index % 2 === 0
            ? videos[
                mediaPairIndex % videos.length
              ]
            : images[
                mediaPairIndex % images.length
              ];
      } else if (hasVideos) {
        /*
         * Excepción necesaria:
         * si solamente existen videos, se repiten los videos.
         */
        mediaItem =
          videos[index % videos.length];
      } else if (hasImages) {
        /*
         * Excepción necesaria:
         * si solamente existen imágenes, se repiten las imágenes.
         */
        mediaItem =
          images[index % images.length];
      }

      return {
        id:
          content?.id ||
          mediaItem?.id ||
          `slide-${index + 1}`,

        content,

        type: mediaItem?.type || 'empty',
        media: mediaItem?.media || '',

        /*
         * Cada video utiliza como poster la imagen que corresponde
         * al mismo número de pareja, cuando existe.
         */
        poster:
          mediaItem?.type === 'video' &&
          hasImages
            ? images[
                Math.floor(index / 2) %
                  images.length
              ]?.media || ''
            : '',

        position:
          content?.position || 'center',

        interval:
          mediaItem?.type === 'video'
            ? VIDEO_FALLBACK_INTERVAL
            : mediaItem?.type === 'image'
              ? IMAGE_INTERVAL
              : EMPTY_MEDIA_INTERVAL,

        isSingleMedia:
          videos.length + images.length === 1,

        hasMedia,
      };
    }
  );
};

const slides = createSlides();

const Slider = () => {
  const carouselRef = useRef(null);
  const videoRefs = useRef([]);
  const timerRef = useRef(null);

  /*
   * Índice real de la diapositiva activa.
   *
   * Los indicadores se calculan posteriormente con respecto
   * a la cantidad de textos disponibles.
   */
  const [activeSlideIndex, setActiveSlideIndex] =
    useState(0);

  const totalTextos = slideContent.length;

  const clearTimer = useCallback(() => {
    if (!timerRef.current) {
      return;
    }

    window.clearTimeout(timerRef.current);
    timerRef.current = null;
  }, []);

  const pauseAllVideos = useCallback(() => {
    videoRefs.current.forEach((video) => {
      if (!video) {
        return;
      }

      video.pause();

      try {
        video.currentTime = 0;
      } catch (error) {
        console.warn(
          'No fue posible reiniciar el video.',
          error
        );
      }
    });
  }, []);

  const goToNextSlide = useCallback(() => {
    const carousel = carouselRef.current;

    if (!carousel || slides.length <= 1) {
      return;
    }

    const nextButton = carousel.querySelector(
      '.capsos-slider-next'
    );

    nextButton?.click();
  }, []);

  const prepareActiveSlide = useCallback(() => {
    const carousel = carouselRef.current;

    if (!carousel) {
      return;
    }

    clearTimer();
    pauseAllVideos();

    const activeSlide = carousel.querySelector(
      '.carousel-item.active'
    );

    if (!activeSlide) {
      return;
    }

    /*
     * Busca la posición real del slide activo.
     *
     * Ejemplo:
     * slide 0 → texto 0
     * slide 1 → texto 1
     * slide 4 → texto 0 nuevamente cuando existen 4 textos
     */
    const carouselItems = Array.from(
      carousel.querySelectorAll('.carousel-item')
    );

    const currentSlideIndex =
      carouselItems.indexOf(activeSlide);

    if (currentSlideIndex >= 0) {
      setActiveSlideIndex(currentSlideIndex);
    }

    const mediaType =
      activeSlide.dataset.mediaType || 'empty';

    const interval = Number(
      activeSlide.dataset.interval ||
        EMPTY_MEDIA_INTERVAL
    );

    if (mediaType === 'video') {
      const video =
        activeSlide.querySelector('video');

      if (!video) {
        timerRef.current = window.setTimeout(
          goToNextSlide,
          interval
        );

        return;
      }

      try {
        video.currentTime = 0;
      } catch (error) {
        console.warn(
          'No fue posible reiniciar el video.',
          error
        );
      }

      video.muted = true;
      video.playsInline = true;

      const playPromise = video.play();

      if (playPromise !== undefined) {
        playPromise.catch(() => {
          timerRef.current = window.setTimeout(
            goToNextSlide,
            interval
          );
        });
      }

      return;
    }

    timerRef.current = window.setTimeout(
      goToNextSlide,
      interval
    );
  }, [
    clearTimer,
    goToNextSlide,
    pauseAllVideos,
  ]);

  const handleBeforeSlide = useCallback(() => {
    clearTimer();
    pauseAllVideos();
  }, [clearTimer, pauseAllVideos]);

  useEffect(() => {
    const carousel = carouselRef.current;

    if (!carousel) {
      return undefined;
    }

    carousel.addEventListener(
      'slide.bs.carousel',
      handleBeforeSlide
    );

    carousel.addEventListener(
      'slid.bs.carousel',
      prepareActiveSlide
    );

    prepareActiveSlide();

    return () => {
      carousel.removeEventListener(
        'slide.bs.carousel',
        handleBeforeSlide
      );

      carousel.removeEventListener(
        'slid.bs.carousel',
        prepareActiveSlide
      );

      clearTimer();
      pauseAllVideos();
    };
  }, [
    clearTimer,
    handleBeforeSlide,
    pauseAllVideos,
    prepareActiveSlide,
  ]);

  return (
    <section
      className="capsos-hero-slider"
      aria-label="Servicios destacados de CAPSOS Telecomunicaciones"
    >
      <div
        id="capsosMainSlider"
        ref={carouselRef}
        className="carousel slide carousel-fade capsos-carousel"
        data-bs-interval="false"
        data-bs-touch="true"
        data-bs-keyboard="true"
      >
        <div className="carousel-inner">
          {slides.map((slide, index) => {
            const content = slide.content;
            const hasMedia = Boolean(slide.media);

            return (
              <div
                key={`${slide.id}-${index}`}
                className={`carousel-item ${
                  index === 0 ? 'active' : ''
                }`}
                data-media-type={slide.type}
                data-interval={slide.interval}
              >
                <article className="capsos-slide-layout">
                  {/* PANEL IZQUIERDO: TEXTOS */}
                  <div className="capsos-slide-copy-panel">
                    {content ? (
                      <div className="capsos-slide-copy">
                        <span className="capsos-slide-category">
                          <span className="capsos-category-line" />

                          {content.category}
                        </span>

                        <h2 className="capsos-slide-title">
                          {content.title}

                          <span>
                            {content.accent}
                          </span>
                        </h2>

                        <p className="capsos-slide-description">
                          {content.description}
                        </p>

                        <div className="capsos-slide-features">
                          {content.features.map(
                            (feature) => (
                              <span key={feature}>
                                <i
                                  className="fas fa-check-circle"
                                  aria-hidden="true"
                                />

                                {feature}
                              </span>
                            )
                          )}
                        </div>

                        <div className="capsos-slide-actions">
                          {content.primaryButton && (
                            <a
                              href={
                                content.primaryButton
                                  .href
                              }
                              className="capsos-slider-button capsos-slider-button-primary"
                            >
                              {
                                content.primaryButton
                                  .text
                              }

                              <i
                                className="fas fa-arrow-right"
                                aria-hidden="true"
                              />
                            </a>
                          )}

                          {content.secondaryButton && (
                            <a
                              href={
                                content
                                  .secondaryButton.href
                              }
                              className="capsos-slider-button capsos-slider-button-secondary"
                            >
                              {
                                content
                                  .secondaryButton.text
                              }
                            </a>
                          )}
                        </div>
                      </div>
                    ) : (
                      <div className="capsos-slide-copy" />
                    )}
                  </div>

                  {/* PANEL DERECHO: VIDEO O IMAGEN */}
                  <div
                    className="capsos-slide-media-panel"
                    style={
                      !hasMedia
                        ? {
                            background:
                              'radial-gradient(circle at 72% 30%, rgba(22, 211, 243, 0.18), transparent 38%), linear-gradient(145deg, #07516f 0%, #03283f 100%)',
                          }
                        : undefined
                    }
                  >
                    {slide.type === 'video' &&
                      hasMedia && (
                        <video
                          ref={(element) => {
                            videoRefs.current[index] =
                              element;
                          }}
                          className="capsos-slide-media"
                          muted
                          autoPlay={index === 0}
                          loop={
                            slide.isSingleMedia &&
                            slides.length === 1
                          }
                          playsInline
                          preload={
                            index === 0
                              ? 'auto'
                              : 'metadata'
                          }
                          poster={
                            slide.poster || undefined
                          }
                          onEnded={
                            slide.isSingleMedia &&
                            slides.length === 1
                              ? undefined
                              : goToNextSlide
                          }
                          style={{
                            objectPosition:
                              slide.position,
                          }}
                          aria-hidden="true"
                        >
                          <source src={slide.media} />

                          Tu navegador no soporta la
                          reproducción de video.
                        </video>
                      )}

                    {slide.type === 'image' &&
                      hasMedia && (
                        <img
                          src={slide.media}
                          className="capsos-slide-media"
                          alt=""
                          aria-hidden="true"
                          loading={
                            index === 0
                              ? 'eager'
                              : 'lazy'
                          }
                          style={{
                            objectPosition:
                              slide.position,
                          }}
                        />
                      )}

                    <div className="capsos-media-overlay" />
                    <div className="capsos-media-vignette" />

                    {hasMedia && (
                      <div className="capsos-media-brand">
                        <span className="capsos-media-brand-dot" />

                        CAPSOS Telecomunicaciones
                      </div>
                    )}
                  </div>
                </article>
              </div>
            );
          })}
        </div>

        {totalTextos > 1 && (
          <div className="capsos-slider-navigation">
            <button
              className="capsos-slider-arrow capsos-slider-prev"
              type="button"
              data-bs-target="#capsosMainSlider"
              data-bs-slide="prev"
              aria-label="Ver diapositiva anterior"
            >
              <i
                className="fas fa-arrow-left"
                aria-hidden="true"
              />
            </button>

            <div className="carousel-indicators capsos-slider-indicators">
              {slideContent.map((content, index) => {
                /*
                 * Cuando las diapositivas superan la cantidad
                 * de textos, el indicador vuelve al primero.
                 *
                 * Ejemplo con cuatro textos:
                 * slide 0 → indicador 0
                 * slide 1 → indicador 1
                 * slide 2 → indicador 2
                 * slide 3 → indicador 3
                 * slide 4 → indicador 0
                 */
                const activeTextIndex =
                  activeSlideIndex % totalTextos;

                const isActive =
                  activeTextIndex === index;

                return (
                  <button
                    key={`indicator-${content.id}-${index}`}
                    type="button"
                    data-bs-target="#capsosMainSlider"
                    data-bs-slide-to={index}
                    className={
                      isActive ? 'active' : ''
                    }
                    aria-current={
                      isActive
                        ? 'true'
                        : undefined
                    }
                    aria-label={`Ir al contenido ${
                      index + 1
                    }`}
                  />
                );
              })}
            </div>

            <button
              className="capsos-slider-arrow capsos-slider-next"
              type="button"
              data-bs-target="#capsosMainSlider"
              data-bs-slide="next"
              aria-label="Ver siguiente diapositiva"
            >
              <i
                className="fas fa-arrow-right"
                aria-hidden="true"
              />
            </button>
          </div>
        )}

        <div className="capsos-slider-scroll">
          <span>Descubre más</span>

          <i
            className="fas fa-chevron-down"
            aria-hidden="true"
          />
        </div>
      </div>
    </section>
  );
};

export default Slider;