import React, {
  useEffect,
  useRef,
  useState,
} from 'react';

import '../css/CapsosImageWall.css';

/* =========================================================
   CARGA AUTOMÁTICA DE IMÁGENES
   Compatible con React + Create React App / Webpack

   Ubicación del componente:
   src/components/home/CapsosImageWall.jsx

   Ubicación de las imágenes:
   src/assets/capsos-gallery/
   ========================================================= */

const imageContext = require.context(
  '../assets/capsos-gallery-optimized',
  true,
  /\.(jpg|jpeg|png|webp|avif|gif)$/i
);

/**
 * Obtiene el nombre del archivo desde una ruta.
 */
const getFileName = (path) => {
  return path.split('/').pop() || path;
};

/**
 * Elimina la extensión del archivo.
 */
const getNameWithoutExtension = (path) => {
  return getFileName(path).replace(/\.[^.]+$/, '');
};

/**
 * Convierte el nombre del archivo en un texto alternativo.
 */
const createAltText = (path) => {
  return getNameWithoutExtension(path)
    .replace(/[-_]+/g, ' ')
    .replace(/\b\w/g, (character) =>
      character.toUpperCase()
    );
};

/**
 * Importa automáticamente las imágenes de la carpeta.
 */
const importedImages = imageContext
  .keys()
  .map((path) => {
    const importedFile = imageContext(path);

    const imageUrl =
      importedFile?.default || importedFile;

    return {
      id: path,
      path,
      src: imageUrl,
      fileName: getFileName(path),
      alt: createAltText(path),
    };
  })
  .filter((image) => Boolean(image.src))
  .sort((firstImage, secondImage) =>
    firstImage.fileName.localeCompare(
      secondImage.fileName,
      'es',
      {
        numeric: true,
        sensitivity: 'base',
      }
    )
  );

/**
 * Busca una imagen que pueda utilizarse como logo.
 */
const logoImage =
  importedImages.find((image) =>
    /logo/i.test(image.fileName)
  ) ||
  importedImages.find((image) =>
    /capsos/i.test(image.fileName)
  ) ||
  null;

/**
 * Excluye el logo de las imágenes de la galería.
 */
const galleryImages = logoImage
  ? importedImages.filter(
      (image) => image.id !== logoImage.id
    )
  : importedImages;

/**
 * Configuración del mosaico.
 */
const VISIBLE_IMAGES = 66;
const CHANGE_INTERVAL = 100;
const FADE_DURATION = 120;

/**
 * Mezcla aleatoriamente las imágenes.
 */
const shuffleImages = (images) => {
  const shuffled = [...images];

  for (
    let index = shuffled.length - 1;
    index > 0;
    index -= 1
  ) {
    const randomIndex = Math.floor(
      Math.random() * (index + 1)
    );

    [
      shuffled[index],
      shuffled[randomIndex],
    ] = [
      shuffled[randomIndex],
      shuffled[index],
    ];
  }

  return shuffled;
};

/**
 * Crea las imágenes iniciales visibles.
 */
const createInitialImages = () => {
  if (!galleryImages.length) {
    return [];
  }

  const shuffled = shuffleImages(galleryImages);

  return Array.from(
    { length: VISIBLE_IMAGES },
    (_, index) => ({
      ...shuffled[index % shuffled.length],
      version: 0,
    })
  );
};

const CapsosImageWall = () => {
  const [visibleImages, setVisibleImages] =
    useState(createInitialImages);

  const [changingIndex, setChangingIndex] =
    useState(null);

  const [hoverPaused, setHoverPaused] =
    useState(false);

  const previousIndexRef = useRef(-1);
  const timeoutRef = useRef(null);
  const changingRef = useRef(false);

  useEffect(() => {
    /**
     * Detiene el cambio de imágenes cuando:
     * - El cursor está sobre la galería.
     * - No hay suficientes imágenes.
     * - No existen posiciones visibles.
     */
    if (
      hoverPaused ||
      galleryImages.length < 2 ||
      visibleImages.length === 0
    ) {
      return undefined;
    }

    /**
     * Cambia una imagen aleatoria del mosaico.
     */
    const changeRandomImage = () => {
      if (changingRef.current) {
        return;
      }

      let selectedIndex = Math.floor(
        Math.random() * visibleImages.length
      );

      /**
       * Evita cambiar consecutivamente
       * la misma posición.
       */
      if (
        visibleImages.length > 1 &&
        selectedIndex === previousIndexRef.current
      ) {
        selectedIndex =
          (selectedIndex + 1) %
          visibleImages.length;
      }

      previousIndexRef.current =
        selectedIndex;

      changingRef.current = true;

      setChangingIndex(selectedIndex);

      timeoutRef.current = window.setTimeout(
        () => {
          setVisibleImages((currentImages) =>
            currentImages.map(
              (currentImage, index) => {
                if (index !== selectedIndex) {
                  return currentImage;
                }

                /**
                 * Evita reemplazar una imagen
                 * por la misma imagen actual.
                 */
                const alternatives =
                  galleryImages.filter(
                    (image) =>
                      image.id !== currentImage.id
                  );

                const source =
                  alternatives.length > 0
                    ? alternatives
                    : galleryImages;

                const randomImageIndex =
                  Math.floor(
                    Math.random() * source.length
                  );

                const replacement =
                  source[randomImageIndex];

                return {
                  ...replacement,
                  version:
                    currentImage.version + 1,
                };
              }
            )
          );

          /**
           * Espera un ciclo de renderizado antes
           * de retirar la clase de transición.
           */
          window.requestAnimationFrame(() => {
            setChangingIndex(null);
            changingRef.current = false;
          });
        },
        FADE_DURATION
      );
    };

    const intervalId = window.setInterval(
      changeRandomImage,
      CHANGE_INTERVAL
    );

    /**
     * Limpieza del efecto.
     */
    return () => {
      window.clearInterval(intervalId);

      if (timeoutRef.current) {
        window.clearTimeout(
          timeoutRef.current
        );

        timeoutRef.current = null;
      }

      changingRef.current = false;
    };
  }, [
    hoverPaused,
    visibleImages.length,
  ]);

  return (
    <section
      className="capsos-image-wall"
      id="galeria-capsos"
      aria-labelledby="capsos-wall-title"
    >
      <div
        className="capsos-mosaic-shell"
        onMouseEnter={() =>
          setHoverPaused(true)
        }
        onMouseLeave={() =>
          setHoverPaused(false)
        }
      >
        {visibleImages.length > 0 ? (
          <div className="capsos-mosaic-grid">
            <div className="capsos-mosaic-logo">
              <div className="capsos-logo-panel">
                {logoImage ? (
                  <img
                    src={logoImage.src}
                    alt="Logo de CAPSOS"
                    className="capsos-logo-image"
                  />
                ) : (
                  <strong className="capsos-logo-fallback">
                    CAPSOS
                  </strong>
                )}

                <span>
                  Conectamos nuestra región
                </span>
              </div>
            </div>

            {visibleImages.map(
              (image, index) => (
                <figure
                  className={`capsos-mosaic-tile ${
                    changingIndex === index
                      ? 'is-changing'
                      : ''
                  }`}
                  key={`capsos-position-${index}`}
                  style={{
                    '--motion-delay': `${
                      (index % 8) * -0.5
                    }s`,
                    '--motion-duration': `${
                      9 + (index % 5)
                    }s`,
                  }}
                >
                  <img
                    key={`${image.id}-${image.version}`}
                    src={image.src}
                    alt={image.alt}
                    className="capsos-mosaic-image"
                    loading={
                      index < 12
                        ? 'eager'
                        : 'lazy'
                    }
                    decoding="async"
                  />

                  <span
                    className="capsos-tile-light"
                    aria-hidden="true"
                  />
                </figure>
              )
            )}
          </div>
        ) : (
          <div
            className="capsos-gallery-empty"
            role="status"
          >
            <i
              className="fas fa-images"
              aria-hidden="true"
            />

            <strong>
              No se encontraron imágenes.
            </strong>

            <span>
              Revisa la carpeta{' '}
              <code>
                src/assets/capsos-gallery
              </code>
              .
            </span>
          </div>
        )}
      </div>
    </section>
  );
};

export default CapsosImageWall;